class Solution {
  private static final long MOD = 1_000_000_007L;

  public int stringCount(int n) {
    // need at least one 'l', one 't' and two 'e': inclusion-exclusion over the three ways to fail
    long all = power(26, n);
    long noL = power(25, n), noT = power(25, n);
    long fewE = power(25, n) + n * power(25, n - 1) % MOD; // zero or one 'e'
    long noLT = power(24, n);
    long noLFewE = power(24, n) + n * power(24, n - 1) % MOD;
    long noTFewE = noLFewE;
    long none = power(23, n) + n * power(23, n - 1) % MOD;
    long bad = (noL + noT + fewE) % MOD;
    long both = (noLT + noLFewE + noTFewE) % MOD;
    long result = ((all - bad + both - none) % MOD + 2 * MOD) % MOD;
    return (int) result;
  }

  private long power(long base, long exp) {
    long result = 1;
    base %= MOD;
    while (exp > 0) {
      if ((exp & 1) == 1) result = result * base % MOD;
      base = base * base % MOD;
      exp >>= 1;
    }
    return result;
  }
}
